      - name: Generate deployed-image SBOM
        if: steps.reuse.outputs.reuse != 'true'
        uses: anchore/sbom-action@e22c389904149dbc22b58101806040fa8d37a610 # v0.24.0
        with:
          image: ${{ steps.image.outputs.reference }}
          syft-version: v1.44.0
          format: spdx-json
          output-file: sbom.spdx.json
          upload-artifact: false

      - name: Scan exact deployed image digest
        uses: aquasecurity/trivy-action@ed142fd0673e97e23eac54620cfb913e5ce36c25 # v0.36.0
        with:
          image-ref: ${{ steps.image.outputs.reference }}
          version: v0.70.0
          format: table
          severity: HIGH,CRITICAL
          exit-code: "1"
          hide-progress: true

      - name: Verify staging infrastructure has no pending changes
        env:
          AWS_ACCESS_KEY_ID: ${{ secrets.STAGING_TERRAFORM_STATE_ACCESS_KEY_ID }}
          AWS_SECRET_ACCESS_KEY: ${{ secrets.STAGING_TERRAFORM_STATE_SECRET_ACCESS_KEY }}
          CLOUDFLARE_API_TOKEN: ${{ secrets.CLOUDFLARE_API_TOKEN }}
          SCW_ACCESS_KEY: ${{ secrets.SCW_ACCESS_KEY }}
          SCW_SECRET_KEY: ${{ secrets.SCW_SECRET_KEY }}
          TF_VAR_container_image: ${{ steps.image.outputs.reference }}
          TF_VAR_runtime_database_password: ${{ secrets.RUNTIME_DATABASE_PASSWORD }}
          TF_VAR_schema_database_password: ${{ secrets.SCHEMA_DATABASE_PASSWORD }}
        run: |
          set +e
          terraform -chdir=infrastructure/scaleway/staging plan \
            -detailed-exitcode \
            -input=false
          plan_status="$?"
          set -e
          if [ "${plan_status}" -eq 2 ]; then
            echo "::error::Staging infrastructure has pending changes. Apply them explicitly, review the result, then rerun this forward deployment."
            exit 1
          fi
          if [ "${plan_status}" -ne 0 ]; then
            exit "${plan_status}"
          fi
          terraform -chdir=infrastructure/scaleway/staging output -json platform > deployment/platform.json
          terraform -chdir=infrastructure/scaleway/staging output -json database > deployment/database.json

      - name: Reconcile role-scoped Secret Manager values
        env:
          PROTECTED_SECRET_VALUES: ${{ secrets.ROLE_SECRET_VALUES_JSON }}
          RUNTIME_DATABASE_PASSWORD: ${{ secrets.RUNTIME_DATABASE_PASSWORD }}
          SCHEMA_DATABASE_PASSWORD: ${{ secrets.SCHEMA_DATABASE_PASSWORD }}
          SCW_ACCESS_KEY: ${{ secrets.SCW_ACCESS_KEY }}
          SCW_SECRET_KEY: ${{ secrets.SCW_SECRET_KEY }}
        run: |
          umask 077
          printf '%s' "${PROTECTED_SECRET_VALUES}" > deployment/protected-secret-values.json
          ops/scaleway/sync-secret-values.sh \
